import networkx as nx
import json
import os
import pandas as pd
from typing import Dict, List


def _edge_cost(G, s, t):
    """Edge cost; missing cost treated as prohibitive so it is avoided."""
    c = G[s][t].get("cost")
    return c if c is not None else 1e9


def _path_cost(G, path):
    """Total cost along a node path."""
    return sum(_edge_cost(G, path[i], path[i + 1]) for i in range(len(path) - 1))


def _tree_path(tree, src, dst):
    """Unique src->dst path in an undirected tree via BFS parent tracking."""
    if src == dst:
        return [src]
    parents = {src: None}
    queue = [src]
    while queue:
        node = queue.pop(0)
        for nb in tree.neighbors(node):
            if nb not in parents:
                parents[nb] = node
                if nb == dst:
                    path = [dst]
                    while parents[path[-1]] is not None:
                        path.append(parents[path[-1]])
                    return path[::-1]
                queue.append(nb)
    return None


def search_algorithm(src, dsts, G, num_partitions):
    """
    Directed Steiner-tree broadcast routing:
    1. Project G to undirected (min cost per node pair) and run
       nx.steiner_tree over terminals {src} + dsts so shared trunk links
       are traversed once instead of once per destination (multicast gain).
    2. For each dst, extract the unique tree path src->dst and use it if it
       is a valid directed route and no costlier than the plain Dijkstra
       path (fallback), so we never exceed the per-destination baseline.
    3. All partitions follow the chosen path for each dst.
    """
    h = G.copy()
    h.remove_edges_from(list(h.in_edges(src)) + list(nx.selfloop_edges(h)))
    bc_topology = BroadCastTopology(src, dsts, num_partitions)

    # Baseline: independent shortest paths (guaranteed valid routes).
    sp_paths = {}
    for dst in dsts:
        try:
            sp_paths[dst] = nx.dijkstra_path(h, src, dst, weight="cost")
        except Exception:
            sp_paths[dst] = None

    # ---- Steiner tree on undirected projection (min cost per pair) ----
    und = nx.Graph()
    for u, v, data in h.edges(data=True):
        c = data.get("cost")
        w = c if c is not None else 1e9
        if und.has_edge(u, v):
            if w < und[u][v]["weight"]:
                und[u][v]["weight"] = w
        else:
            und.add_edge(u, v, weight=w)

    tree = None
    terminals = [src] + [d for d in dsts if d in und]
    if len(terminals) > 1 and und.number_of_edges() > 0:
        try:
            tree = nx.steiner_tree(und, terminals, weight="weight")
        except Exception:
            tree = None

    # ---- Choose route per dst: tree path if valid & not costlier ----
    chosen = {}
    for dst in dsts:
        best_path = sp_paths.get(dst)
        best_cost = _path_cost(h, best_path) if best_path else float("inf")
        if tree is not None and dst in tree and src in tree:
            tpath = _tree_path(tree, src, dst)
            if tpath is not None and all(
                h.has_edge(tpath[k], tpath[k + 1]) for k in range(len(tpath) - 1)
            ):
                tcost = _path_cost(h, tpath)
                if tcost <= best_cost:  # ties go to tree -> maximize sharing
                    best_path, best_cost = tpath, tcost
        if best_path is None:
            best_path = nx.dijkstra_path(h, src, dst, weight="cost")
        chosen[dst] = best_path

    for dst in dsts:
        path = chosen[dst]
        for i in range(0, len(path) - 1):
            s, t = path[i], path[i + 1]
            for j in range(bc_topology.num_partitions):
                bc_topology.append_dst_partition_path(dst, j, [s, t, G[s][t]])

    return bc_topology


class SingleDstPath(Dict):
    partition: int
    edges: List[List]  # [[src, dst, edge data]]


class BroadCastTopology:
    def __init__(self, src: str, dsts: List[str], num_partitions: int = 4, paths: Dict[str, SingleDstPath] = None):
        self.src = src  # single str
        self.dsts = dsts  # list of strs
        self.num_partitions = num_partitions

        # dict(dst) --> dict(partition) --> list(nx.edges)
        # example: {dst1: {partition1: [src->node1, node1->dst1], partition 2: [src->dst1]}}
        if paths is not None:
            self.paths = paths
            self.set_graph()
        else:
            self.paths = {dst: {str(i): None for i in range(num_partitions)} for dst in dsts}

    def get_paths(self):
        print(f"now the set path is: {self.paths}")
        return self.paths

    def set_num_partitions(self, num_partitions: int):
        self.num_partitions = num_partitions

    def set_dst_partition_paths(self, dst: str, partition: int, paths: List[List]):
        """
        Set paths for partition = partition to reach dst
        """
        partition = str(partition)
        self.paths[dst][partition] = paths

    def append_dst_partition_path(self, dst: str, partition: int, path: List):
        """
        Append path for partition = partition to reach dst
        """
        partition = str(partition)
        if self.paths[dst][partition] is None:
            self.paths[dst][partition] = []
        self.paths[dst][partition].append(path)

def make_nx_graph(cost_path=None, throughput_path=None, num_vms=1):
    """
    Default graph with capacity constraints and cost info
    nodes: regions, edges: links
    per edge:
        throughput: max tput achievable (gbps)
        cost: $/GB
        flow: actual flow (gbps), must be < throughput, default = 0
    """
    # Use relative path from this file's location
    current_dir = os.path.dirname(os.path.abspath(__file__))

    if cost_path is None:
        cost = pd.read_csv(os.path.join(current_dir, "profiles/cost.csv"))
    else:
        cost = pd.read_csv(cost_path)

    if throughput_path is None:
        throughput = pd.read_csv(os.path.join(current_dir, "profiles/throughput.csv"))
    else:
        throughput = pd.read_csv(throughput_path)

    G = nx.DiGraph()
    for _, row in throughput.iterrows():
        if row["src_region"] == row["dst_region"]:
            continue
        G.add_edge(row["src_region"], row["dst_region"], cost=None, throughput=num_vms * row["throughput_sent"] / 1e9)

    for _, row in cost.iterrows():
        if row["src"] in G and row["dest"] in G[row["src"]]:
            G[row["src"]][row["dest"]]["cost"] = row["cost"]

    # some pairs not in the cost grid
    no_cost_pairs = []
    for edge in G.edges.data():
        src, dst = edge[0], edge[1]
        if edge[-1]["cost"] is None:
            no_cost_pairs.append((src, dst))
    print("Unable to get costs for: ", no_cost_pairs)

    return G


